from itertools import combinations

# We need to partition {1, 2, ..., 16} into 4 subsets each summing to 34
# Let's use a backtracking approach

def solve():
    numbers = list(range(1, 17))
    target = 34
    n_subsets = 4

    # Try to find 4 disjoint subsets each summing to 34
    # We'll use a recursive approach

    def find_subsets(remaining, subsets_found):
        if subsets_found == n_subsets:
            if len(remaining) == 0:
                return []
            return None

        # Find all subsets of remaining that sum to target
        # Start with the smallest element to avoid duplicates
        if not remaining:
            return None

        first = remaining[0]
        # Try to find a subset containing 'first' that sums to target
        for size in range(1, len(remaining) + 1):
            for combo in combinations(remaining, size):
                if sum(combo) == target and first in combo:
                    # Found a valid subset
                    new_remaining = [x for x in remaining if x not in combo]
                    result = find_subsets(new_remaining, subsets_found + 1)
                    if result is not None:
                        return [list(combo)] + result
        return None

    result = find_subsets(numbers, 0)
    return result

subsets = solve()
if subsets:
    print("Found solution:")
    for i, s in enumerate(subsets):
        print(f"Subset {i}: {s}, sum = {sum(s)}")

    # Create the assignment list
    assignment = [0] * 16
    for subset_idx, subset in enumerate(subsets):
        for num in subset:
            assignment[num - 1] = subset_idx
    print(f"Assignment: {assignment}")
else:
    print("UNSATISFIABLE")
